INSERT INTO trucker.store_ch
  (id, store_id, rec_start_date, rec_end_date, closed_date_sk, store_name,
   number_employees, floor_space, hours, manager, market_id, geography_class,
   market_desc, market_manager, division_id, division_name, company_id,
   company_name, street_number, street_name, street_type, suite_number,
   city, county, state, zip, country, gmt_offset, tax_precentage, deleted)
SELECT r.id,
       argMaxState(r.store_id,        now64()),
       argMaxState(r.rec_start_date,  now64()),
       argMaxState(r.rec_end_date,    now64()),
       argMaxState(r.closed_date_sk::Int32,  now64()),
       argMaxState(r.store_name,      now64()),
       argMaxState(r.number_employees::Int32, now64()),
       argMaxState(r.floor_space::Int32,      now64()),
       argMaxState(r.hours,           now64()),
       argMaxState(r.manager,         now64()),
       argMaxState(r.market_id::Int32, now64()),
       argMaxState(r.geography_class, now64()),
       argMaxState(r.market_desc,     now64()),
       argMaxState(r.market_manager,  now64()),
       argMaxState(r.division_id::Int32, now64()),
       argMaxState(r.division_name,   now64()),
       argMaxState(r.company_id::Int32, now64()),
       argMaxState(r.company_name,    now64()),
       argMaxState(r.street_number,   now64()),
       argMaxState(r.street_name,     now64()),
       argMaxState(r.street_type,     now64()),
       argMaxState(r.suite_number,    now64()),
       argMaxState(r.city,            now64()),
       argMaxState(r.county,          now64()),
       argMaxState(r.state,           now64()),
       argMaxState(r.zip,             now64()),
       argMaxState(r.country,         now64()),
       argMaxState(r.gmt_offset::Float64,     now64()),
       argMaxState(r.tax_precentage::Float64, now64()),
       argMaxState({{ .operation | eq "delete" }}, now64())
FROM {{ .rows }}
GROUP BY id
